 banner=f'<svg class="course-banner" viewBox="0 0 900 180" role="img" aria-label="{E(c["title"])}"><defs><linearGradient id="course-bg"><stop stop-color="#0a101b"/><stop offset="1" stop-color="#313746"/></linearGradient></defs><rect width="900" height="180" fill="url(#course-bg)"/><text x="35" y="56" font-family="Arial" font-size="12" letter-spacing="3" fill="#c9d3e4">INACT COURSES · CHOOSE YOUR DIRECTION</text><text x="35" y="125" font-family="Georgia" font-size="45" fill="#fff">Learn. Practice. Build.</text><path d="M640 90H830" stroke="#b4c0d4" opacity=".35"/><path class="workflow-light" d="M640 90H830" stroke="#fff" stroke-width="3"/>'+''.join(f'<circle cx="{650+i*80}" cy="90" r="25" fill="#121823" stroke="#c7d1e1" opacity=".8"/>' for i in range(3))+'</svg>'
 related=[x for x in courses if x['id'] in c.get('related',[])]
 resources='<p><a href="#curriculum">Return to this course’s learning route ↓</a></p>'+''.join(f'<p><a href="{x["id"]}.html">{E(x["title"])} →</a></p>' for x in related)+''.join(f'<p><a href="../articles/{x["slug"]}.html">Read an available deeper lesson →</a></p>' for x in c['published'])
 watch=watch_section(c['videos']) if c['videos'] else '<section class="watch-section"><h2>Learn from the written lesson.</h2><p>Optional publisher videos will be selected as this course develops. The explanations, examples, and practice stand on their own.</p></section>'
 nav='<a class="platinum" href="../index.html#courses">Explore another course →</a>'
 form=''.join(f'<label for="plan-{i}">{E(t)}</label><textarea id="plan-{i}" data-plan="{i}" placeholder="Write a practical answer you can use."></textarea>' for i,t in enumerate(['What do you want to be able to do?','What small task will you try this week?','What will you check, and who can give you feedback?']))
 schema={'@context':'https://schema.org','@type':'WebPage','name':c['title']+' course and foundation lesson','description':c['deck'],'url':'https://inactentertainment.github.io/ie/'+c['url']}
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(c['title'])} | InAct Courses</title><meta name="description" content="{E(c['deck'])}"><link rel="canonical" href="{schema['url']}"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/article.css"><link rel="stylesheet" href="../assets/courses.css"><link rel="stylesheet" href="../assets/learning-ui.css"><link rel="stylesheet" href="../assets/read-aloud.css"><script type="application/ld+json">{json.dumps(schema)}</script><link rel="stylesheet" href="../assets/business-dictionary.css"><link rel="stylesheet" href="../assets/brand-refresh.css"></head><body class="article-page course-page" data-course="{slug}" style="--course-tint:{c['tint']}"><a class="skip" href="#course">Skip to course</a>{header}{release}<main class="article-shell" id="course"><div class="article-hero">{banner}<h1>{E(c['title'])}</h1><p class="deck">{E(c['deck'])}</p><p class="article-meta-line">{E(c['stage'])} · Independent course · Six-module curriculum<br>Published foundation lesson, practice, and learning plan. Full curriculum modules are still being developed.</p><div class="reader-actions"><a class="platinum" href="#curriculum">Explore your curriculum ↓</a><a class="outline" href="../index.html#courses">All courses</a><button class="platinum" id="lights-toggle" aria-pressed="false">Lights on ☀</button></div><p class="course-outcome"><strong>What you’ll build</strong>{E(c['outcome'])}</p></div><section class="course-overview"><h2>{E(h)}</h2><p>{E(p1)}</p><p>{E(p2)}</p><p>{E(p3)}</p></section>{learning_markup(slug)}<div class="learning-loop"><div><strong>Understand</strong><p>Start with plain words, a useful question, and one worked example.</p></div><div><strong>Watch</strong><p>Hear a perspective, notice a choice, and pause to think.</p></div><div><strong>Practice</strong><p>Try a small task. Use feedback to make the next attempt better.</p></div><div><strong>Build</strong><p>Make something you can use, test it, and reflect on the result.</p></div></div><section id="curriculum"><span class="eyebrow">Your learning route</span><h2>From the basics to your own project.</h2><p>These six modules outline the full course we are building. Planned topics are not yet full lessons. Start with the published foundation lesson below; available deeper lessons are linked in their relevant modules. No other course is required.</p><div class="reader-actions"><a class="platinum" href="#foundation-unit">Start the foundation lesson ↓</a></div><div class="module-grid">{''.join(modules)}</div></section>{foundation_markup(slug)}{watch}<section class="platinum-panel orientation-form"><span class="panel-kicker">Your first step</span><h2>Make a plan you can use.</h2>{form}<fieldset class="project-review"><legend>Check the work you create</legend><p class="small">This is a self-review, not a graded credential. Rate your work and choose what to improve.</p><label for="review-clarity">Clarity: Can someone understand the purpose?</label><select id="review-clarity" data-plan="clarity"><option value="">Choose a review</option><option>Needs a clearer explanation</option><option>Clear enough to test</option><option>Clear and supported by an example</option></select><label for="review-evidence">Evidence: Did you check the important facts?</label><select id="review-evidence" data-plan="evidence"><option value="">Choose a review</option><option>Important facts still need checking</option><option>Main facts checked</option><option>Facts checked and limitations explained</option></select><label for="review-usefulness">Usefulness: Does it help with the real task?</label><select id="review-usefulness" data-plan="usefulness"><option value="">Choose a review</option><option>Needs a better fit with the task</option><option>Ready for a small test</option><option>Tested and revised after feedback</option></select></fieldset><p class="small">Your plan stays in this browser on this device. No account or server storage. Download it to keep your own copy.</p><p id="plan-status" class="small" role="status"></p><button class="platinum" id="download-plan">Download my learning plan ↓</button></section><section class="references-list related-learning"><div class="related-heading"><h2>Keep learning with InAct.</h2><div class="related-links">{resources}</div></div><p class="small">Continue with the curriculum or a related InAct course. The videos above are optional examples; the written explanations and your practice do not depend on them.</p></section><div class="course-navigation"><div class="reader-actions">{nav}</div></div></main>{footer_markup(home)}<div class="toast" id="toast" hidden role="status"></div><script src="../assets/site.js"></script><script src="../assets/video.js"></script><script src="../assets/learning-ui.js"></script><script src="../assets/read-aloud.js"></script><script src="../assets/course-plan.js"></script><script src="../assets/course-unit.js"></script><script src="../assets/footer.js"></script><script src="../assets/learning-term-links.js"></script></body></html>'''
 Path('output/'+c['url']).write_text(page)
